from dsl import *

# Theme: Health & Fitness — men's health, healthy ageing 50+, mobility, balance, longevity habits.
# Every app carries a medical-style disclaimer; prompts give general information and route decisions to clinicians.

# 1 — Fall-proofing the home and habits (complements exercise-led balance apps)
APP("fall_proof", "Fall Proof", "Make your home and habits fall-proof after 60", "Health & Fitness", ["#00695C", "#FFA000", "#5D4037"], "shield",
 "Fall Proof audits your home room by room from photos, checks the medicines, footwear and lighting that quietly raise fall risk, and gives you a rehearsed plan for the night-time trip and for the fall itself.",
 "You are an occupational therapist specialising in falls prevention: practical, respectful of independence, precise about cheap fixes first.",
 "Most falls are preventable", "A few details let us tailor the audit.", ["Room-by-room hazard scans from photos", "Medicine, footwear and lighting checks", "A rehearsed plan for if you fall"],
 [NAME, NUM("age", "Age", "72"), CH("home", "Home", ["House with stairs", "Bungalow", "Flat", "Sheltered housing"], "House with stairs"), CH("lives", "Lives", ["Alone", "With partner", "With family"], "With partner")],
 [T("scan", "Scan a room", "Photo → hazards and fixes", "📷", [PHOTO("Photo of a room, hallway, stairs or bathroom", "", True)],
    "Inspect the room photo for fall hazards (rugs, cords, lighting, clutter, thresholds, grab points, furniture height, wet floors). Sections: a table (Hazard | Where | Risk level | Fix | Approx. cost), a checklist of free fixes to do today, and a callout on the single highest-risk item.", "table, checklist, callout", "Scan room", "Looking around…"),
  T("audit", "Whole-home audit", "Room-by-room checklist, cheapest first", "🏠", [CH("rooms", "Rooms to cover", ["Bathroom", "Bedroom", "Stairs & hall", "Kitchen", "Outside & entrance"], "Bathroom", multi=True), TXT("done", "Already fitted", "grab rail by the toilet, night light on the landing")],
    "Build a falls audit for the profile's home covering {rooms}, skipping anything already fitted: {done}. Sections: a checklist per room of what to check and fix, ordered cheapest first, a table (Fix | Cost band | Who can fit it | Priority), bullets on grants, occupational-therapy referrals and equipment services that often exist for older residents, and a callout on the three fixes with the strongest evidence (lighting, rails, removing loose rugs).", "checklist, table, bullets, callout", "Run the audit", "Checking corners…"),
  T("meds", "Medicines & dizziness", "Which ones raise fall risk", "💊", [LONG("meds", "Medicines and supplements", "amlodipine, zopiclone, codeine for the knee"), CH("dizzy", "Dizzy on standing?", ["Never", "Sometimes", "Often"], "Sometimes")],
    "Review these medicines for the profile as general information only: {meds}; dizziness on standing: {dizzy}. Sections: a table (Medicine | Class | Fall-related effect to be aware of | Ask the pharmacist about), bullets of the questions to raise at a medication review (timing, dose, alternatives, standing slowly), steps for a safe stand-up routine (sit on the edge, count to ten, hold something, then go), and a callout that no medicine should be stopped or changed without the prescriber.", "table, bullets, steps, callout", "Review meds", "Reading labels…"),
  T("night", "Night-time plan", "Safer trips to the bathroom", "🌙", [NUM("trips", "Bathroom trips per night", "2"), TXT("route", "Bedroom to bathroom route", "landing, four steps, bathroom door")],
    "Plan safe night-time trips for the profile ({trips} per night, route: {route}). Sections: steps for the trip itself (wake fully, sit, light on, footwear, hold the rail), a checklist of setup (motion-sensor lights, cleared path, bedside items, a commode or bottle if appropriate), a kv of evening habits that reduce trips (fluid timing, caffeine, alcohol, legs up in the afternoon), and a callout on when frequent night-time urination is worth mentioning to a doctor.", "steps, checklist, kv, callout", "Plan nights", "Dimming lights…"),
  T("getup", "If I fall", "Getting up safely, and the plan", "🆘", [CH("situation", "Practise for", ["Getting up from the floor", "Fall outdoors", "Fall at night alone"], "Getting up from the floor")],
    "Coach the profile through '{situation}'. Sections: steps for the safe sequence (check for injury, roll, crawl to a sturdy chair, kneel, rise) with one cue per step, bullets on what to do if you cannot get up (warmth, moving joints, calling for help), a checklist of preparation (phone placement, alarm pendant, keys with a neighbour), and a callout on injuries that mean stay put and call emergency services.", "steps, bullets, checklist, callout", "Coach me", "Practising…")],
 "General information, not medical advice. Never stop or change a medicine without the prescriber, and see a doctor after any fall with injury, blackout or new dizziness.")

# 2 — Men's screening schedule & doctor conversations
APP("under_the_hood", "Under the Hood", "The men's health check-up schedule you keep skipping", "Health & Fitness", ["#37474F", "#FF6F00", "#00ACC1"], "wrench",
 "Under the Hood tells men exactly which health checks are due at their age, scripts the awkward conversations with a doctor, and turns family history and habits into a clear risk map.",
 "You are a straight-talking men's health GP: no lectures, no jargon, always clear about which checks are age-based guidance and which depend on personal history.",
 "Book the service you've been putting off", "Your age and family history decide what's due.", ["Screening timeline for your age", "Scripts for awkward appointments", "Family-history risk map"],
 [NAME, NUM("age", "Age", "52"), CH("smoker", "Smoking", ["Never", "Quit", "Current"], "Never"), TXT("family", "Family history", "dad heart attack at 60, uncle prostate cancer")],
 [T("due", "What's due now", "Checks for your age", "📋", [TXT("last", "Last checks you remember", "BP 2 years ago, never had cholesterol done"), TXT("country", "Country", "UK")],
    "For the profile's age, smoking status and family history, with last checks: {last}, in {country}. Sections: a table (Check | Why for you | Typical frequency | Status: due / soon / fine), a checklist of what to book this month in priority order, bullets on what each test involves (time, fasting, discomfort), and a callout that screening intervals vary by national guidance and personal history.", "table, checklist, bullets, callout", "Show what's due", "Checking the log…"),
  T("script", "Say it to the doctor", "Words for the awkward stuff", "🗣️", [CH("topic", "Topic", ["Low mood", "Drinking too much", "Snoring and daytime tiredness", "A mole or skin change", "Chest tightness on exertion", "Weight", "Something else"], "Low mood"), TXT("detail", "Details", "flat and short-tempered for 3 months")],
    "The user needs to raise '{topic}' with a doctor; details: {detail}. Sections: a quote with a two-sentence opener they can say word for word, bullets of the facts to bring (when it started, pattern, what makes it better or worse), a kv of the questions the doctor will likely ask and how to answer briefly, and a callout on why this topic is routine for GPs and what to expect in the exam.", "quote, bullets, kv, callout", "Write my opener", "Finding words…"),
  T("risk", "Family risk map", "What runs in the family", "🧬", [LONG("history", "Relatives and conditions", "father: heart attack 58; mother: type 2 diabetes; brother: bowel polyps")],
    "Map this family history for the profile: {history}. Sections: a table (Condition | Relative | Age at onset | Your relevance: higher / average / unclear), bullets of which screenings this history may bring forward and by roughly how much, steps for what to ask about at the next appointment, and a callout that family history raises questions, not diagnoses.", "table, bullets, steps, callout", "Map it", "Tracing…"),
  T("decode", "Decode my results", "Photo or paste of a blood test", "🔬", [PHOTO("Photo of the results sheet"), TXT("paste", "Or paste the numbers", "total cholesterol 6.1, HDL 1.0, PSA 2.4")],
    "Explain these results in plain English (from the photo and/or: {paste}). Sections: a table (Marker | Your value | Typical range | Plain-English meaning), bullets of lifestyle levers that affect each flagged marker, a kv of questions to ask the doctor about anything outside range, and a callout that ranges vary by lab and only the ordering clinician can interpret them for you.", "table, bullets, kv, callout", "Explain", "Reading the sheet…"),
  T("mot", "Habit MOT", "Ten-minute lifestyle audit", "🔧", [CH("drinks", "Drinks per week", ["0", "1–7", "8–14", "15–21", "22+"], "8–14"), NUM("waist", "Waist (cm)", "98"), CH("move", "Weekly exercise", ["None", "Under 75 min", "75–150 min", "150+ min"], "Under 75 min")],
    "Run a lifestyle MOT for the profile: {drinks} drinks per week, waist {waist} cm, exercise {move}. Sections: a table (Area | Your status | Target | Gap), cards for the three highest-impact changes (meta = effort · payoff), steps for the first two weeks, and a callout on waist size as a heart and diabetes risk marker.", "table, cards, steps, callout", "Run the MOT", "Lifting the bonnet…")],
 "General information, not medical advice or a substitute for your doctor. Screening guidance differs by country and personal history; seek urgent care for chest pain, blood in urine or stool, or a testicular lump.")

